use ratatui::{prelude::*, widgets::*}; use crate::app::{App, Toast, ToastLevel}; pub fn draw(f:&mut Frame, app:&App, t:&Toast, area:Rect){ let w=(t.message.len() as u16 + 8).min(area.width.saturating_sub(4)); let r=Rect{x:area.x+area.width.saturating_sub(w+2), y:area.y+2, width:w, height:3}; let icon=match t.level{ToastLevel::Success=>"✓",ToastLevel::Warning=>"⚠",ToastLevel::Error=>"✗",ToastLevel::Info=>"•"}; let color=match t.level{ToastLevel::Success=>app.theme.success,ToastLevel::Warning=>app.theme.warning,ToastLevel::Error=>app.theme.error,ToastLevel::Info=>app.theme.accent}; f.render_widget(Clear,r); f.render_widget(Paragraph::new(format!("{} {}",icon,t.message)).style(Style::default().fg(color)).block(Block::bordered().border_style(Style::default().fg(color))), r); }